{"path":"/root/workspace/solution.py","content":"from __future__ import annotations

from fractions import Fraction
from math import cos, sin, sqrt, radians
from pathlib import Path
from typing import Any
import re

import numpy as np
import spglib


def _parse_cif(filepath: str):
    """Parse a CIF file into a spglib cell tuple (lattice, positions, numbers).

    This parser is intentionally lightweight and tailored for standard CIFs
    containing a single atom-site loop with fractional coordinates.
    """
    text = Path(filepath).read_text()
    lines = text.splitlines()

    cell = {}
    atom_rows = []

    # Collect cell parameters
    for line in lines:
        if line.startswith("_cell_length_a"):
            cell["a"] = float(line.split()[1])
        elif line.startswith("_cell_length_b"):
            cell["b"] = float(line.split()[1])
        elif line.startswith("_cell_length_c"):
            cell["c"] = float(line.split()[1])
        elif line.startswith("_cell_angle_alpha"):
            cell["alpha"] = float(line.split()[1])
        elif line.startswith("_cell_angle_beta"):
            cell["beta"] = float(line.split()[1])
        elif line.startswith("_cell_angle_gamma"):
            cell["gamma"] = float(line.split()[1])

    # Parse atom-site loop by looking for headers and reading rows until next loop/data item
    i = 0
    while i < len(lines):
        if lines[i].strip() == "loop_":
            j = i + 1
            headers = []
            while j < len(lines) and lines[j].lstrip().startswith("_"):
                headers.append(lines[j].strip())
                j += 1
            if any(h.startswith("_atom_site_") for h in headers):
                # Map header name to column index
                header_map = {h: idx for idx, h in enumerate(headers)}
                # Required columns
                type_key = None
                x_key = y_key = z_key = None
                for h in headers:
                    if h in ("_atom_site_type_symbol", "_atom_site_label") and type_key is None:
                        type_key = h
                    elif h == "_atom_site_fract_x":
                        x_key = h
                    elif h == "_atom_site_fract_y":
                        y_key = h
                    elif h == "_atom_site_fract_z":
                        z_key = h
                if type_key and x_key and y_key and z_key:
                    k = j
                    while k < len(lines):
                        row = lines[k].strip()
                        if not row:
                            k += 1
                            continue
                        if row.startswith("_") or row == "loop_" or row.lower().startswith("data_"):
                            break
                        parts = row.split()
                        if len(parts) >= len(headers):
                            symbol = parts[header_map[type_key]]
                            # Strip common charge/oxidation annotations, e.g. Fe4+ -> Fe
                            element = re.sub(r"[^A-Za-z]", "", symbol)
                            x = float(parts[header_map[x_key]])
                            y = float(parts[header_map[y_key]])
                            z = float(parts[header_map[z_key]])
                            atom_rows.append((element, np.array([x, y, z], dtype=float)))
                        k += 1
                    i = k
                    continue
            i = j
        else:
            i += 1

    if not atom_rows:
        raise ValueError(f"No atom sites found in CIF: {filepath}")
    if not all(k in cell for k in ("a", "b", "c", "alpha", "beta", "gamma")):
        raise ValueError(f"Incomplete cell parameters in CIF: {filepath}")

    a, b, c = cell["a"], cell["b"], cell["c"]
    alpha, beta, gamma = map(radians, (cell["alpha"], cell["beta"], cell["gamma"]))

    lattice = np.array(
        [
            [a, 0.0, 0.0],
            [b * cos(gamma), b * sin(gamma), 0.0],
            [
                c * cos(beta),
                c * (cos(alpha) - cos(beta) * cos(gamma)) / max(sin(gamma), 1e-12),
                c
                * sqrt(
                    max(
                        0.0,
                        1
                        + 2 * cos(alpha) * cos(beta) * cos(gamma)
                        - cos(alpha) ** 2
                        - cos(beta) ** 2
                        - cos(gamma) ** 2,
                    )
                )
                / max(sin(gamma), 1e-12),
            ],
        ],
        dtype=float,
    )

    positions = np.array([p for _, p in atom_rows], dtype=float)
    elements = [e for e, _ in atom_rows]
    species_map = {}
    numbers = []
    for e in elements:
        if e not in species_map:
            species_map[e] = len(species_map) + 1
        numbers.append(species_map[e])

    return (lattice, positions, np.array(numbers, dtype=int))


def _rational_str(x: float, max_denominator: int = 12) -> str:
    # Normalize to [0, 1) before rationalizing.
    x = float(x) % 1.0
    if abs(x - 1.0) < 1e-8 or abs(x) < 1e-8:
        return "0"
    f = Fraction(x).limit_denominator(max_denominator)
    if f.numerator == f.denominator:
        return "1"
    return f"{f.numerator}/{f.denominator}" if f.denominator != 1 else str(f.numerator)


def analyze_wyckoff_position_multiplicities_and_coordinates(filepath: str) -> dict[str, dict] | dict[str, Any]:
    """Analyze Wyckoff position multiplicities and representative coordinates.

    Returns a dictionary with:
      - wyckoff_multiplicity_dict: mapping wyckoff letter -> multiplicity
      - wyckoff_coordinates_dict: mapping wyckoff letter -> first atom coordinate
        rounded to simple rational fractions.
    """
    try:
        cell = _parse_cif(filepath)
        dataset = spglib.get_symmetry_dataset(cell, symprec=1e-3)
        if dataset is None:
            raise ValueError("spglib could not determine symmetry dataset")

        wyckoffs = list(dataset["wyckoffs"])
        equivalent_atoms = np.array(dataset["equivalent_atoms"], dtype=int)
        positions = np.array(cell[1], dtype=float)

        # Representative index for each symmetry-equivalent orbit.
        rep_to_indices: dict[int, list[int]] = {}
        for idx, rep in enumerate(equivalent_atoms):
            rep_to_indices.setdefault(int(rep), []).append(idx)

        wyckoff_multiplicity_dict: dict[str, int] = {}
        wyckoff_coordinates_dict: dict[str, list[str]] = {}

        for rep, indices in rep_to_indices.items():
            letter = wyckoffs[rep]
            if letter not in wyckoff_multiplicity_dict:
                wyckoff_multiplicity_dict[letter] = len(indices)
                coord = positions[rep]
                wyckoff_coordinates_dict[letter] = [_rational_str(v) for v in coord]

        # Sort by letter for stable output.
        wyckoff_multiplicity_dict = dict(sorted(wyckoff_multiplicity_dict.items(), key=lambda kv: kv[0]))
        wyckoff_coordinates_dict = dict(sorted(wyckoff_coordinates_dict.items(), key=lambda kv: kv[0]))

        return {
            "wyckoff_multiplicity_dict": wyckoff_multiplicity_dict,
            "wyckoff_coordinates_dict": wyckoff_coordinates_dict,
        }
    except Exception as exc:
        return {"error": str(exc)}


if __name__ == "__main__":
    import sys
    print(analyze_wyckoff_position_multiplicities_and_coordinates(sys.argv[1]))
"}
